INSERT INTO public.products (id, title, category, tagline, price, badge, image, description, specs, variants, in_stock)
VALUES
  ('rose-blossom', 'The Rose Sucker', 'toys', 'BESTSELLER • AIR-PULSE SUCTION', 25000, 'BESTSELLER • AIR-PULSE SUCTION', '/assets/product-rose.webp', 'Sculpted like an innocent blooming rose, engineered like an absolute powerhouse. Uses gentle aerodynamic air-wave pulses to stimulate without direct friction, taking you from a teasing flutter to an undeniable crescendo in minutes.', ARRAY['Material: 100% Medical-Grade Liquid Silicone', 'Sound Level: < 30 dB (Whisper Silent)', 'Waterproof: IPX7 — Waterproof', 'Battery: Magnetic USB Rechargeable']::text[], '[{"name":"Red","price":25000,"priceStr":"₦25,000","img":"/assets/product-rose.webp"},{"name":"Black","price":25000,"priceStr":"₦25,000","img":"/assets/product-rose.webp"},{"name":"Pink","price":25000,"priceStr":"₦25,000","img":"/assets/product-rose.webp"},{"name":"Purple","price":25000,"priceStr":"₦25,000","img":"/assets/product-rose.webp"},{"name":"Yellow","price":25000,"priceStr":"₦25,000","img":"/assets/product-rose.webp"},{"name":"Green","price":25000,"priceStr":"₦25,000","img":"/assets/product-rose.webp"}]'::jsonb, true),
  ('pulsating-rose', 'Pulsating Rose', 'toys', 'NEW • SUCKER & LICKER', 35000, 'NEW • SUCKER & LICKER', '/assets/rose-pair-duo.webp', 'Dual oral sensation options sculpted into a blooming rose silhouette. Choose the Sucker for airtight pulsing flutter waves, or the Licker for rhythmic tongue-stroking ecstasy.', ARRAY['Material: 100% Medical-Grade Liquid Silicone', 'Sound Level: < 30 dB (Whisper Silent)', 'Waterproof: IPX7 — Waterproof', 'Battery: Magnetic USB Rechargeable']::text[], '[{"name":"Sucker","price":35000,"priceStr":"₦35,000","img":"/assets/rose-sucker-variant.webp"},{"name":"Licker","price":35000,"priceStr":"₦35,000","img":"/assets/rose-licker-variant.webp"}]'::jsonb, true),
  ('sceptre-wand', 'The Mini Wand', 'toys', 'DEEP RUMBLE • POCKET MASSAGER', 15000, 'DEEP RUMBLE • POCKET MASSAGER', '/assets/product-wand.webp', 'Don’t let the compact silhouette fool you. The Mini Wand packs full-sized, bone-deep vibrations into a palm-sized frame with a 360° flexible silicone head. Perfect for pinpoint clitoral stimulation, all-over tension relief, or slipping into an overnight bag.', ARRAY['Material: Silky Medical Silicone & Textured Grip', 'Sound Level: < 30 dB (Subtle & Discreet)', 'Waterproof: Splashproof & Easy Clean', 'Battery: USB Fast Charging']::text[], '[{"name":"Black","price":15000,"priceStr":"₦15,000","img":"/assets/product-wand.webp"},{"name":"Pink","price":15000,"priceStr":"₦15,000","img":"/assets/mini-wand-colors.webp"},{"name":"Purple","price":15000,"priceStr":"₦15,000","img":"/assets/mini-wand-colors.webp"},{"name":"Green","price":15000,"priceStr":"₦15,000","img":"/assets/mini-wand-colors.webp"}]'::jsonb, true),
  ('siren-app', 'Siren App-Controlled', 'toys', 'APP CONNECT • LONG DISTANCE', 27000, 'APP CONNECT • LONG DISTANCE', '/assets/siren-app.webp', 'Long distance? What distance? Discreet, whisper-quiet, and ergonomically curved to slip seamlessly into your panties. Hand full control over to your partner from across the room or across the globe via smartphone app—or surrender to customized rhythm playlists and music vibration modes.', ARRAY['Material: Silky Medical Liquid Silicone', 'Sound Level: < 30 dB (Discreet in Public)', 'Waterproof: IPX7 — Waterproof', 'Connectivity: Bluetooth App Sync (iOS & Android)', 'Battery: Magnetic USB Rechargeable']::text[], '[{"name":"Red","price":27000,"priceStr":"₦27,000","img":"/assets/siren-app-red.webp"},{"name":"White","price":27000,"priceStr":"₦27,000","img":"/assets/siren-app-white.webp"}]'::jsonb, true),
  ('lipstick-vibe', 'The Lipstick Vibrator', 'toys', 'RECHARGEABLE • STEALTH LUXE', 22000, 'RECHARGEABLE • STEALTH LUXE', '/assets/lipstick-vibe.webp', 'The ultimate embarrassment-proof secret. Disguised in plain sight as a chic white and gold designer lipstick. Toss it into your handbag, cosmetic pouch, or desk drawer without fear—nobody will ever look twice. Features a velvet-soft angled silicone bullet, multiple whisper-quiet vibration speeds, and convenient USB recharging.', ARRAY['Material: Medical-Grade Soft Silicone & Gold Alloy', 'Sound Level: < 25 dB (Total Stealth)', 'Discretion: Authentic Lipstick Silhouette', 'Battery: Discreet USB Rechargeable']::text[], '[]'::jsonb, true),
  ('sculpted-dildo', 'The Contour Shaft', 'toys', 'DUAL SIZE • SUCTION BASE', 15000, 'DUAL SIZE • SUCTION BASE', '/assets/dildo-trio.webp', 'Anatomically sculpted with a lifelike contoured shaft, raised head, and heavy-duty hands-free suction base that mounts firmly to shower tiles, mirrors, and flat surfaces. Fully harness-ready and crafted from velvety, body-safe material. Choose between 6" (₦15,000) and 7" (₦17,000) in three rich skin tones.', ARRAY['Material: Ultra-Pure Medical PVC & Body-Safe Silicone', 'Mounting: Heavy-Duty Hands-Free Suction Base', 'Waterproof: 100% Waterproof & Submersible', 'Compatibility: Harness Ready & Shower Compatible']::text[], '[{"name":"6\" Tan","price":15000,"priceStr":"₦15,000","img":"/assets/dildo-tan.webp"},{"name":"6\" Brown","price":15000,"priceStr":"₦15,000","img":"/assets/dildo-bronze.webp"},{"name":"6\" Black","price":15000,"priceStr":"₦15,000","img":"/assets/dildo-noir.webp"},{"name":"7\" Tan","price":17000,"priceStr":"₦17,000","img":"/assets/dildo-tan.webp"},{"name":"7\" Brown","price":17000,"priceStr":"₦17,000","img":"/assets/dildo-bronze.webp"},{"name":"7\" Black","price":17000,"priceStr":"₦17,000","img":"/assets/dildo-noir.webp"}]'::jsonb, true),
  ('thrusting-dildo', 'Remote Thrusting Shaft', 'toys', 'REMOTE CONTROLLED • MOTORIZED THRUST', 45000, 'REMOTE CONTROLLED • MOTORIZED THRUST', '/assets/thrusting-dildo-duo.webp', 'Unstoppable motorized rhythm at the press of a button. Engineered with high-torque reciprocating thrusting mechanics and deep vibration rumbles, completely controlled hands-free via wireless ergonomic remote. Features a heavy-duty suction base that locks firmly onto flat surfaces or shower tiles.', ARRAY['Material: Ultra-Pure Body-Safe Silicone & Suction Base', 'Action: Motorized Reciprocating Thrusting & Rumbles', 'Control: Wireless Ergonomic Remote Control (Included)', 'Mounting: Heavy-Duty Hands-Free Suction Lock Base', 'Waterproof: IPX7 Waterproof Shaft (Shower & Wash Safe)', 'Battery: USB Magnetic Rechargeable Shaft']::text[], '[{"name":"Black","price":45000,"priceStr":"₦45,000","img":"/assets/thrusting-dildo-black.webp"},{"name":"Brown","price":45000,"priceStr":"₦45,000","img":"/assets/thrusting-dildo-brown.webp"},{"name":"Tan","price":45000,"priceStr":"₦45,000","img":"/assets/thrusting-dildo-tan.webp"}]'::jsonb, true),
  ('sucking-rabbit', 'The Sucking Rabbit', 'toys', 'AIR-PULSE SUCTION • DUAL STIM', 35000, 'AIR-PULSE SUCTION • DUAL STIM', '/assets/sucking-rabbit.webp', 'The legendary rabbit silhouette reimagined for absolute sensory overload. Combines fluttering air-pulse clitoral suction ears with a flexible, deeply ribbed shaft designed to reach and stimulate the G-spot. Independent dual motor controls let you tailor your vibration speed and suction intensity simultaneously.', ARRAY['Material: Silky Medical-Grade Liquid Silicone & Pearlescent Handle', 'Dual Stimulation: Air-Wave Clitoral Suction + G-Spot Shaft Vibration', 'Sound Level: < 35 dB (Discreet & Powerful)', 'Waterproof: IPX7 Waterproof (Fully Submersible in Bath/Shower)', 'Battery: Magnetic USB Fast Rechargeable']::text[], '[]'::jsonb, true),
  ('non-vibrating-plugs', 'Sculpted Contour Plugs', 'toys', 'NON-VIBRATING • 3 SIZES', 8000, 'NON-VIBRATING • 3 SIZES', '/assets/plugs-vault-chest.webp', 'Anatomically tapered for seamless insertion and effortless all-day wear. Crafted in premium non-porous body-safe materials with a slim ergonomic neck and wide flared anchor base for complete safety and confidence. Available in Small (₦8,000), Medium (₦9,000), and Large (₦10,000).', ARRAY['Finishes: Velvet Silicone & Mirror Chrome with Faceted Gems', 'Safety: Slim Flexible Neck with Flared Anchor Base', 'Calibrated Sizing: Small (₦8k) • Medium (₦9k) • Large (₦10k)', 'Waterproof: 100% Waterproof & Submersible (Temperature Play Ready)', 'Hygiene: Non-Porous, Hypoallergenic & Easy to Clean']::text[], '[{"name":"Small","price":8000,"priceStr":"₦8,000","img":"/assets/plug-size-small.webp"},{"name":"Medium","price":9000,"priceStr":"₦9,000","img":"/assets/plug-size-medium.webp"},{"name":"Large","price":10000,"priceStr":"₦10,000","img":"/assets/plug-size-large.webp"}]'::jsonb, true),
  ('rabbit-cock-ring', 'The Rabbit Cock Ring', 'toys', 'RECHARGEABLE • DUAL STAMINA', 25000, 'RECHARGEABLE • DUAL STAMINA', '/assets/rabbit-cock-ring.webp', 'Engineered for shared ecstasy and extended stamina. Crafted from ultra-stretchy, silky liquid silicone with an ergonomic dual-loop design that gently restricts blood flow for firmer, longer-lasting erections while simultaneously thrilling her clitoris with powerful buzzing rabbit ears.', ARRAY['Material: 100% Ultra-Elastic Medical Liquid Silicone', 'Couples Function: Erection Support + Clitoral Flutter Teaser', 'Sound Level: < 30 dB (Whisper Quiet Power)', 'Waterproof: IPX7 Waterproof (Shower & Bath Safe)', 'Battery: Magnetic USB Fast Rechargeable']::text[], '[]'::jsonb, true),
  ('creature-cock-ring', 'Creature Ergonomic Cock Ring', 'toys', 'STAMINA LOCK • NON-VIBRATING', 15000, 'STAMINA LOCK • NON-VIBRATING', '/assets/creature-cock-ring.webp', 'Engineered by S-HANDE for unmatched stamina control and extended endurance. Crafted from velvety, medical-grade liquid silicone with an ergonomic contoured spine and dual-retention loops. Locks firm blood flow, prolongs hardness, separates testicles comfortably, and provides an effortless hands-free grip without vibration distraction.', ARRAY['Brand & Model: S-HANDE Creature Ergonomic Cock Ring', 'Material: 100% Medical-Grade Liquid Silicone', 'Length: 142 mm (5.59 inches)', 'Dual Loops: 34 mm Base Ring & 47 mm Retention Loop', 'Function: Non-Vibrating Stamina Lock & Delay', 'Waterproof: 100% Waterproof & Submersible']::text[], '[]'::jsonb, true),
  ('pocket-bullet', 'Velvet Pocket Bullet', 'toys', 'POCKET POWER • 10 MODES', 15000, 'POCKET POWER • 10 MODES', '/assets/bullet-vibe-all-colors.webp', 'Pure concentrated power in a sleek, lipstick-sized silhouette. Engineered with a whisper-quiet high-torque micro motor and 10 dynamic pulse patterns. Features a velvety soft-touch silicone body (or mirror chrome) with single-button intuitive control. Travel-friendly, 100% waterproof, and completely discreet.', ARRAY['Vibration Modes: 10 Multi-Speed Rhythms & Pulses', 'Finishes: 5 Colorways (Fuchsia, Black, Blush, Purple, Chrome)', 'Sound Level: < 35 dB (Sub-Whisper Travel Friendly)', 'Waterproof: IPX7 Waterproof (Bath & Shower Safe)', 'Portability: Compact Pocket & Purse Scale']::text[], '[{"name":"Fuchsia","price":15000,"priceStr":"₦15,000","img":"/assets/bullet-vibe-all-colors.webp"},{"name":"Black","price":15000,"priceStr":"₦15,000","img":"/assets/bullet-vibe-matte-trio.webp"},{"name":"Blush Pink","price":15000,"priceStr":"₦15,000","img":"/assets/bullet-vibe-matte-trio.webp"},{"name":"Purple","price":15000,"priceStr":"₦15,000","img":"/assets/bullet-vibe-matte-trio.webp"},{"name":"Chrome","price":15000,"priceStr":"₦15,000","img":"/assets/bullet-vibe-all-colors.webp"}]'::jsonb, true),
  ('contour-bullet-6inch', 'The 6" Heart Bullet', 'toys', '6 INCHES • 🎬 VIDEO', 18000, '6 INCHES • 🎬 VIDEO', '/assets/bullet-6inch-in-hand.webp', 'Extended 6-inch slender reach capped with a brilliant chrome crown and tactile heart button. Features 10 escalating vibration rumbles and flutter rhythms engineered for pinpoint clitoral and full-body pleasure. USB rechargeable with whisper-silent motor and liquid silicone finish.', ARRAY['Length: 6.0 inches (152 mm) Slender Silhouette', 'Control: One-Touch Tactile Heart Button & Chrome Crown', 'Vibration Modes: 10 Multi-Speed Rhythms & Escalating Pulses', 'Sound Level: < 35 dB (Discreet Whisper Power)', 'Waterproof: IPX7 Waterproof (Bath & Shower Safe)', 'Battery: USB Magnetic Fast Rechargeable']::text[], '[{"name":"Purple","price":18000,"priceStr":"₦18,000","img":"/assets/bullet-6inch-in-hand.webp"},{"name":"Black","price":18000,"priceStr":"₦18,000","img":"/assets/bullet-6inch-in-hand.webp"},{"name":"Fuchsia","price":18000,"priceStr":"₦18,000","img":"/assets/bullet-6inch-in-hand.webp"}]'::jsonb, true),
  ('sleek-bullet-7inch', 'The 7" Sleek Bullet', 'toys', '7 INCHES • 🎬 VIDEO', 20000, '7 INCHES • 🎬 VIDEO', '/assets/bullet-7inch-metallic-pair.webp', 'Extended 7-inch luxury metallic silhouette delivering high-velocity deep rumbling vibrations. Available in a seamless flat-top magnetic rechargeable edition and a classic fast-charging pin edition. Fully waterproof, whisper quiet, and ergonomically balanced for pinpoint sensations.', ARRAY['Length: 7.0 inches (178 mm) Extended Shaft', 'Charging Variants: Magnetic Contact (Flat Top) / Fast DC Pin', 'Vibration Modes: 10 Multi-Frequency Rumbles & Waves', 'Sound Level: < 35 dB (Discreet Luxury Power)', 'Waterproof: IPX7 Waterproof (Bath & Shower Safe)', 'Battery: USB Fast Rechargeable']::text[], '[{"name":"Magnetic Charger","price":20000,"priceStr":"₦20,000","img":"/assets/bullet-7inch-magnetic-pin-pair.webp"},{"name":"Pin Charger","price":20000,"priceStr":"₦20,000","img":"/assets/bullet-7inch-floral-display.webp"}]'::jsonb, true),
  ('rose-jump-egg', 'Rose Jump Egg: App-Controlled Egg', 'toys', 'APP CONNECT • 🎬 VIDEO', 28000, 'APP CONNECT • 🎬 VIDEO', '/assets/rose-jump-egg-kit.webp', 'Discreet, ultra-powerful egg vibrator with an ergonomic retrieval tail and external teaser tip. Seamlessly syncs with your smartphone for intimate long-distance partner control, customized vibration playlists, sound-activated pulsing, and explosive pinpoint pleasure whether at home or out in public.', ARRAY['Control: Smartphone App (iOS & Android) + Manual Base Control', 'Long Distance: Global Partner Control via Internet Sync', 'Design: Ergonomic Jump Egg with External Teaser Tail', 'Sound Level: < 30 dB (Discreet In-Public Wear)', 'Waterproof: IPX7 Waterproof & Easy Clean', 'Battery: USB Fast Rechargeable (Pin Cable Included)']::text[], '[]'::jsonb, true),
  ('african-brute', 'African Brute Herbal Tincture', 'lubes', 'STAMINA', 27000, 'STAMINA', '/assets/african-brute.webp', 'An authentic African botanical elixir scientifically crafted with 8 potent natural aphrodisiac extracts including Corynanthe Yohimbe, Muira Puama, and Cola Acuminata. Formulated to enhance stamina, maximize blood flow to sensitive zones, revitalize libido, and intensify climax sensations.', ARRAY['Volume: 500ml Oral Liquid Tonic', 'Certification: NAFDAC Reg No. A7-5237L', 'Active Formula: 8 Traditional African Botanical Extracts', 'Directions: 5 Tablespoons (40ml) 30–40 mins before intimacy']::text[], '[]'::jsonb, true)
